-- The ward checklist joins the platform questionnaire library: what a hospital department
-- checks about itself before an audit (cleanliness, materials, medicines, narcotics, equipment,
-- forms, fridges, sterile supplies, dress code, clinical risk). Generated from
-- src/features/quality/audits/seed/ward.js (tests/auditProgramme.test.js checks they agree).
-- A hospital copies it and adds its own questions; the self-assessments use it too.

with s as (select '{"k":"ward","s":"other","v":"Εσωτερικός έλεγχος τμήματος","t":"Λίστα ελέγχου κλινικού τμήματος (αυτοαξιολόγηση)","d":"Λίστα ελέγχου για την αυτοαξιολόγηση ενός κλινικού τμήματος πριν από την επιθεώρηση: καθαριότητα, υλικά, φάρμακα, ναρκωτικά, μηχανήματα, έντυπα, ψυγεία, αποστειρωμένα, προσωπικό, κλινική επικινδυνότητα. Επεξεργάσιμη: δημιουργήστε αντίγραφο για το νοσοκομείο σας και προσθέστε ερωτήσεις.","sc":"Κλινικά τμήματα και μονάδες νοσηλείας.","dt":["clinical"],"ch":[{"r":"ΓΕΝ","t":"Γενικά","q":[["ΓΕΝ-1","Είναι αριθμημένα όλα τα βιβλία και τα τετράδια του τμήματος;","Βιβλία τμήματος","",1,false,[]],["ΓΕΝ-2","Αναγράφεται στα μπουκάλια αντισηπτικού και απολυμαντικού η ημερομηνία που ανοίχτηκαν ή μεταγγίστηκαν, και χρησιμοποιούνται εντός της διάρκειάς τους;","Επιθεώρηση μπουκαλιών","",1,false,[]],["ΓΕΝ-3","Λαμβάνονται τα κατάλληλα μέτρα προφύλαξης ανάλογα με τον λοιμογόνο παράγοντα του ασθενούς;","Παρατήρηση, πινακίδες προφύλαξης","",2,true,[]],["ΓΕΝ-4","Γνωρίζει το προσωπικό πώς διαχειρίζεται έναν μολυσματικό ασθενή και πώς γίνεται η απομόνωση;","Συνέντευξη προσωπικού, πρωτόκολλο απομόνωσης","",2,true,[]]]},{"r":"ΚΑΘ","t":"Καθαριότητα","q":[["ΚΑΘ-1","Γνωρίζει το προσωπικό ποιο είναι το πρωτόκολλο καθαριότητας του τμήματος και πώς διαχειρίζονται τα απορρίμματα;","Πρωτόκολλο καθαριότητας, συνέντευξη","",1,false,[]],["ΚΑΘ-2","Γνωρίζει το προσωπικό ποια πανάκια καθαριότητας αντιστοιχούν σε ποιες επιφάνειες;","Παρατήρηση, χρωματική κωδικοποίηση","",1,false,[]],["ΚΑΘ-3","Τοποθετούνται τα μολυσματικά απορρίμματα σε ειδικό σάκο ή δοχείο με πάντα κλειστό καπάκι και δεν μεταγγίζονται;","Παρατήρηση","",2,true,[]],["ΚΑΘ-4","Διαχειρίζονται σωστά τα αιχμηρά αντικείμενα (ειδικός κάδος, όχι υπερπλήρης, χωρίς επανατοποθέτηση καλύμματος);","Παρατήρηση κάδων αιχμηρών","",2,true,[]],["ΚΑΘ-5","Καθαρίζονται και απολυμαίνονται όλα τα μηχανήματα και οι εξοπλισμοί του τμήματος με καταγραφή;","Φύλλο καθαρισμού μηχανημάτων","",1,false,[]],["ΚΑΘ-6","Καθαρίζονται και τακτοποιούνται τα τροχήλατα, οι πάγκοι και ο ιματισμός;","Επιθεώρηση χώρου","",1,false,[]],["ΚΑΘ-7","Είναι καθαρά τα στόμια των υποδοχέων σαπουνιού και αντισηπτικού;","Επιθεώρηση νιπτήρων","",1,false,[]]]},{"r":"ΥΛ","t":"Υλικά","q":[["ΥΛ-1","Γίνεται κάθε μήνα έλεγχος των υλικών που λήγουν εντός εξαμήνου και καταγράφεται;","Φύλλο ελέγχου λήξεων υλικών","",2,true,[]],["ΥΛ-2","Γίνεται κατά την παραλαβή υλικών ποιοτικός και ποσοτικός έλεγχος και υπογράφεται το σχετικό έντυπο;","Έντυπα παραλαβής","",1,false,[]],["ΥΛ-3","Είναι όλα τα υλικά πάνω σε ράφια, χωρίς να υπάρχει τίποτα τοποθετημένο στο δάπεδο;","Επιθεώρηση αποθήκης","",1,false,[]],["ΥΛ-4","Αποθηκεύονται τα υλικά κατά ημερομηνία λήξης (τα πιο κοντινά μπροστά);","Επιθεώρηση ραφιών","",1,false,[]],["ΥΛ-5","Προσέχεται η τοποθέτηση στα ράφια, ώστε τα υλικά και οι συσκευασίες να μην τσακίζουν;","Επιθεώρηση ραφιών","",1,false,[]]]},{"r":"ΦΑΡ","t":"Φάρμακα","q":[["ΦΑΡ-1","Γίνεται κάθε μήνα έλεγχος των φαρμάκων που λήγουν εντός εξαμήνου και καταγράφεται;","Φύλλο ελέγχου λήξεων φαρμάκων","",2,true,[]],["ΦΑΡ-2","Γίνεται κατά την παραλαβή φαρμάκων ποιοτικός και ποσοτικός έλεγχος και υπογράφεται το σχετικό έντυπο;","Έντυπα παραλαβής φαρμάκων","",1,false,[]],["ΦΑΡ-3","Γνωρίζει το προσωπικό πώς διαχειρίζεται τα φάρμακα με παρόμοια όψη ή ονομασία (SALAD);","Συνέντευξη, σήμανση ραφιών","",2,true,[]],["ΦΑΡ-4","Γνωρίζει το προσωπικό πώς διαχειρίζεται τα φάρμακα υψηλού κινδύνου (HAM);","Συνέντευξη, σήμανση φαρμάκων υψηλού κινδύνου","",2,true,[]],["ΦΑΡ-5","Είναι σωστή η αποθήκευση των φαρμάκων και γνωρίζει το προσωπικό τι ελέγχεται και κάθε πότε;","Επιθεώρηση φαρμακείου τμήματος","",1,false,[]],["ΦΑΡ-6","Αναγράφεται η ημερομηνία ανοίγματος στα σιρόπια και φυλάσσονται στο ψυγείο για 28 ημέρες ή όσο αναγράφει το σκεύασμα;","Επιθεώρηση ψυγείου φαρμάκων","",1,false,[]],["ΦΑΡ-7","Για τα φάρμακα με ορισμένο χρόνο διατήρησης μετά το άνοιγμα, αναγράφεται ο χρόνος σύμφωνα με τις οδηγίες του φαρμάκου;","Επιθεώρηση φαρμάκων","",1,false,[]]]},{"r":"ΝΑΡ","t":"Ναρκωτικά","q":[["ΝΑΡ-1","Καταγράφονται τα σκευάσματα και οι ποσότητες στο πρώτο φύλλο του βιβλίου ναρκωτικών;","Βιβλίο ναρκωτικών","",2,true,[]],["ΝΑΡ-2","Γίνεται παραλαβή και παράδοση σε κάθε βάρδια, χωρίς διορθώσεις με μουντζούρα ή blanco;","Βιβλίο ναρκωτικών","",2,true,[]],["ΝΑΡ-3","Όταν αλλάζει το σκεύασμα, αλλάζει και η ονομασία στα αντίστοιχα φάρμακα του βιβλίου;","Βιβλίο ναρκωτικών","",1,false,[]],["ΝΑΡ-4","Φυλάσσεται το κενό σκεύασμα, ώστε να επιστραφεί στο φαρμακείο για αντικατάσταση;","Επιθεώρηση φύλαξης","",1,false,[]],["ΝΑΡ-5","Όταν χορηγείται ½ αμπούλα και η υπόλοιπη πετιέται, το καταγράφουν στις παρατηρήσεις δύο υπεύθυνα άτομα;","Παρατηρήσεις βιβλίου ναρκωτικών","",2,true,[]],["ΝΑΡ-6","Καταγράφεται πάντα και η περιεκτικότητα του σκευάσματος;","Βιβλίο ναρκωτικών","",1,false,[]]]},{"r":"ΜΗΧ","t":"Μηχανήματα","q":[["ΜΗΧ-1","Φέρουν όλα τα μηχανήματα ταμπελάκι συντήρησης με ισχύουσα ημερομηνία;","Επιθεώρηση μηχανημάτων","",2,true,[]]]},{"r":"ΕΝΤ","t":"Έντυπα, πρωτόκολλα και κανονισμοί","q":[["ΕΝΤ-1","Γνωρίζει το προσωπικό από ποια μοναδική πηγή εκτυπώνει τα κωδικοποιημένα έντυπα;","Συνέντευξη προσωπικού","",1,false,[]],["ΕΝΤ-2","Γνωρίζει το προσωπικό πού μπορεί να αναζητήσει τα πρωτόκολλα και τις οδηγίες, γραπτώς και ηλεκτρονικά;","Συνέντευξη προσωπικού","",1,false,[]],["ΕΝΤ-3","Γνωρίζει το προσωπικό πού μπορεί να αναζητήσει τους κανονισμούς και τις διαδικασίες, γραπτώς και ηλεκτρονικά;","Συνέντευξη προσωπικού","",1,false,[]]]},{"r":"ΨΥΓ","t":"Ψυγεία και κατάψυξη","q":[["ΨΥΓ-1","Είναι σωστή η θερμοκρασία των ψυγείων;","Ένδειξη θερμομέτρου, όρια θερμοκρασίας","",2,true,[]],["ΨΥΓ-2","Καταγράφονται οι θερμοκρασίες των ψυγείων σε κάθε ημέρα λειτουργίας;","Φύλλο καταγραφής θερμοκρασιών","",2,true,[]],["ΨΥΓ-3","Ελέγχονται τα ψυγεία (πάγος, έγκαιρη απόψυξη, καθαριότητα) και καταγράφεται ο έλεγχος;","Φύλλο ελέγχου ψυγείων","",1,false,[]],["ΨΥΓ-4","Για τα φάρμακα που ανοίχτηκαν και τοποθετούνται στο ψυγείο, αναγράφεται η ημερομηνία που ανοίχτηκαν;","Επιθεώρηση ψυγείου","",1,false,[]]]},{"r":"ΚΑΡ","t":"Τροχήλατο καρδιοαναπνευστικής ανάνηψης και βιοϊατρικός εξοπλισμός","q":[["ΚΑΡ-1","Ελέγχονται τακτικά ο βιοϊατρικός εξοπλισμός, τα φάρμακα και τα υλικά του τροχηλάτου σύμφωνα με το δελτίο ελέγχου (απινιδωτής);","Δελτίο ελέγχου τροχηλάτου και απινιδωτή","",2,true,[]],["ΚΑΡ-2","Είναι το τροχήλατο κλειδωμένο με σφραγίδα και γίνεται έλεγχος και αναπλήρωση των υλικών μετά από κάθε χρήση;","Σφραγίδα, δελτίο ελέγχου","",2,true,[]]]},{"r":"ΑΠΟ","t":"Αποστειρωμένα","q":[["ΑΠΟ-1","Ελέγχεται η ημερομηνία λήξης των αποστειρωμένων υλικών;","Επιθεώρηση αποστειρωμένων","",2,true,[]],["ΑΠΟ-2","Ελέγχεται η ακεραιότητα της συσκευασίας των αποστειρωμένων υλικών;","Επιθεώρηση αποστειρωμένων","",2,true,[]],["ΑΠΟ-3","Ελέγχονται οι δείκτες αποστείρωσης πριν από τη χρήση;","Δείκτες αποστείρωσης","",1,false,[]],["ΑΠΟ-4","Είναι σωστές οι συνθήκες φύλαξης των αποστειρωμένων (καθαρός, στεγνός χώρος, μακριά από υγρασία);","Επιθεώρηση χώρου φύλαξης","",1,false,[]],["ΑΠΟ-5","Είναι σωστή η διακίνηση των υλικών από και προς την αποστείρωση;","Παρατήρηση, έντυπα διακίνησης","",1,false,[]]]},{"r":"ΠΡΟ","t":"Προσωπικό","q":[["ΠΡΟ-1","Τηρεί το προσωπικό τον κώδικα ενδυμασίας (στολές, νύχια, μαλλιά, κοσμήματα) και φέρει κάρτα εργασίας;","Παρατήρηση","",1,false,[]]]},{"r":"ΚΛΕ","t":"Κλινική επικινδυνότητα","q":[["ΚΛΕ-1","Γνωρίζει το προσωπικό πώς κατηγοριοποιούνται και αναφέρονται τα συμβάντα;","Συνέντευξη, έντυπο αναφοράς συμβάντος","",1,false,[]],["ΚΛΕ-2","Καταγράφονται και αναφέρονται οι πτώσεις ασθενών;","Αναφορές συμβάντων τμήματος","",2,true,[]],["ΚΛΕ-3","Καταγράφονται και αναφέρονται οι κατακλίσεις;","Αναφορές συμβάντων τμήματος","",2,true,[]],["ΚΛΕ-4","Καταγράφονται και ελέγχονται τα σημεία φλεβοθρόμβωσης;","Φύλλο παρακολούθησης φλεβικών προσπελάσεων","",1,false,[]],["ΚΛΕ-5","Αναφέρονται και αναλύονται τα νοσηλευτικά λάθη και οι παρ’ ολίγον συμβάντα;","Αναφορές συμβάντων τμήματος","",2,true,[]]]},{"r":"ΤΡΑ","t":"Τραπεζοκομία","q":[["ΤΡΑ-1","Τηρείται το διαιτολόγιο κάθε ασθενούς και διανέμεται ο σωστός δίσκος φαγητού;","Διαιτολόγιο ασθενών, παρατήρηση διανομής","",1,false,[]],["ΤΡΑ-2","Ελέγχεται ο δίσκος συνοδού και τηρούνται οι κανόνες υγιεινής στα κομοδίνα και στον χώρο της κουζίνας του τμήματος;","Επιθεώρηση","",1,false,[]]]},{"r":"ΤΡΟ","t":"Τροχήλατο καθαριότητας","q":[["ΤΡΟ-1","Διαθέτει το τροχήλατο καθαριότητας τα απολυμαντικά, τα κουβαδάκια, τα πανιά, τα γάντια και τις σφουγγαρίες που προβλέπει το πρωτόκολλο;","Επιθεώρηση τροχηλάτου","",1,false,[]]]},{"r":"ΑΠΘ","t":"Αποθηκευτικός χώρος","q":[["ΑΠΘ-1","Υπάρχει αποθηκευτικός χώρος επιμελείας στο τμήμα, τακτοποιημένος και καθαρός;","Επιθεώρηση χώρου","",1,false,[]]]}]}'::jsonb j),
tp as (insert into public.quality_audit_templates (organization_id, is_system, template_key, standard, standard_version, title, description, scope, department_types, active, version, source)
 select null, true, j->>'k', j->>'s', j->>'v', j->>'t', j->>'d', j->>'sc', array(select jsonb_array_elements_text(j->'dt')), true, 1, 'seed' from s
 on conflict on constraint quality_audit_templates_title_key do nothing returning id),
qs as (select ch.value->>'r' r, ch.value->>'t' t, q.value v, row_number() over (order by ch.ordinality, q.ordinality) p
 from s, jsonb_array_elements(j->'ch') with ordinality ch, jsonb_array_elements(ch.value->'q') with ordinality q)
insert into public.quality_audit_template_questions (template_id, organization_id, position, chapter_ref, chapter_title, clause_ref, question, guidance, evidence, weight, critical, areas)
select tp.id, null, qs.p, qs.r, qs.t, qs.v->>0, qs.v->>1, nullif(qs.v->>3, ''), nullif(qs.v->>2, ''), (qs.v->>4)::numeric, (qs.v->>5)::boolean, array(select jsonb_array_elements_text(qs.v->6)) from tp, qs;
